// Transform Open-Meteo response to CanonicalWeather format
try {
  const webhookData = $node['Webhook Trigger'].json?.body ?? {};
  const geocodeData = $node['Geocode City'].json ?? {};
  const weatherData = $node['Get Weather'].json ?? {};

  // Check for geocoding errors
  if (!geocodeData.results || geocodeData.results.length === 0) {
    return [{
      json: {
        status: 'error',
        error: `City not found: ${webhookData.city ?? 'unknown'}`,
        meta: {
          provider: 'open-meteo',
          timestamp: new Date().toISOString(),
          requestedCity: webhookData.city ?? 'unknown'
        }
      }
    }];
  }

  // Check for weather API errors
  if (weatherData.error || !weatherData.current) {
    return [{
      json: {
        status: 'error',
        error: weatherData.reason ?? 'Failed to fetch weather data',
        meta: {
          provider: 'open-meteo',
          timestamp: new Date().toISOString(),
          requestedCity: webhookData.city ?? 'unknown'
        }
      }
    }];
  }

  const location = geocodeData.results[0];
  const current = weatherData.current;

  // Build canonical response
  const canonical = {
    location: {
      city: location.name,
      country: location.country,
      latitude: location.latitude,
      longitude: location.longitude
    },
    current: {
      temperature: current.temperature_2m,
      feelsLike: current.apparent_temperature,
      humidity: current.relative_humidity_2m,
      windSpeed: current.wind_speed_10m,
      windDirection: current.wind_direction_10m,
      weatherCode: current.weather_code,
      pressure: current.surface_pressure
    },
    meta: {
      provider: 'open-meteo',
      timestamp: new Date().toISOString(),
      requestedCity: webhookData.city ?? 'unknown'
    },
    status: 'success'
  };

  return [{ json: canonical }];
} catch (error) {
  return [{
    json: {
      status: 'error',
      error: error.message,
      meta: {
        provider: 'open-meteo',
        timestamp: new Date().toISOString(),
        requestedCity: 'unknown'
      }
    }
  }];
}
